-- Universo — migração 0027: cláusulas gerais do contrato no Gestor de cláusulas e dados bancários da Empresa
-- (Cid, 21/11/2026; etapa 1 do emissor de contratos).
--
-- O contrato tem 15 seções fixas (1 Partes · 2 Objeto · 3 Escopo · 4 Prazos · 5 Ajustes e aprovações · 6 Honorários
-- e pagamento · 7 Despesas reembolsáveis · 8 Obrigações do contratante · 9 Obrigações da contratada · 10 Alterações
-- de escopo e aditivos · 11 Direitos autorais e imagem · 12 Confidencialidade e LGPD · 13 Força maior e rescisão ·
-- 14 Encerramento e disposições gerais · 15 Foro e assinatura). Cada seção mistura:
--   * dados de outras ferramentas (Empresa, Equipe, Contatos, proposta, PGT, Honorários) — montados pelo emissor,
--     não guardados aqui (a estrutura está em odisse-orcamentos/contrato-minuta.js);
--   * cláusulas dos eventos do PGT (pgt_eventos.clausula, como já era);
--   * cláusulas gerais, aqui (grupo 'geral'): texto redigido no Gestor, com
--       secao     1–15;
--       titulo    nome curto, só para o Gestor e o editor (não sai no contrato);
--       tipo      'fixa' (entra sempre) ou 'opcional' (o Cid assente ou não em cada contrato; padrao = vem marcada);
--       condicao  nulo = sempre; senão só entra quando o contrato pede:
--                 projeto_legal (há a etapa PL) · legal_executiva (PL e alguma etapa da fase Executiva) ·
--                 despesas (alguma despesa reembolsável marcada) · co_clientes (mais de um contratante).
-- Marcas no texto que o emissor troca pelos dados: {proposta} (nº da proposta), {etapa_aprovada} (campo do contrato).
-- O texto foi tirado dos contratos de 2023 (CPS) e revisto com o Cid em 21/11; precisa da leitura de um advogado.
-- Tratamento sempre no masculino: "o CONTRATANTE" (Cid, 21/11). Sem testemunhas: assinatura eletrônica.
ALTER TABLE vendas_clausulas ADD COLUMN secao INTEGER CHECK (secao BETWEEN 1 AND 15);
ALTER TABLE vendas_clausulas ADD COLUMN titulo TEXT;
ALTER TABLE vendas_clausulas ADD COLUMN tipo TEXT NOT NULL DEFAULT 'opcional' CHECK (tipo IN ('fixa', 'opcional'));
ALTER TABLE vendas_clausulas ADD COLUMN condicao TEXT CHECK (condicao IN ('projeto_legal', 'legal_executiva', 'despesas', 'co_clientes'));
CREATE INDEX vendas_clausulas_secao ON vendas_clausulas (grupo, secao, ordem);


-- O RRT, que nos contratos antigos era cláusula solta, passa a ser mais uma despesa reembolsável.
SELECT 'vcl_rrt', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'despesa',
  'Taxa do Registro de Responsabilidade Técnica (RRT), recolhida pela CONTRATADA junto ao CAU.', 1,
  COALESCE((SELECT MAX(ordem) FROM vendas_clausulas WHERE grupo = 'despesa' AND arquivado_em IS NULL), 0) + 1;

-- Empresa: dados bancários para o pagamento dos contratos (O Estúdio › Empresa). Ficam só no banco: não vão para a
-- cópia pública da Marca; marketing e site não os enxergam (campos_restritos).
ALTER TABLE empresa ADD COLUMN banco TEXT;
ALTER TABLE empresa ADD COLUMN agencia TEXT;
ALTER TABLE empresa ADD COLUMN conta TEXT;
ALTER TABLE empresa ADD COLUMN pix TEXT;
