INSERT INTO vendas_clausulas (id, criado_em, atualizado_em, criado_por, atualizado_por, grupo, secao, titulo, tipo, condicao, texto, padrao, ordem) VALUES
  ('vcl_c01_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 1, 'Solidariedade dos contratantes', 'opcional', 'co_clientes', 'Havendo mais de um CONTRATANTE, todos respondem solidariamente pelas obrigações deste contrato.', 1, 101),
  ('vcl_c01_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 1, 'Fórmula de abertura', 'fixa', NULL, 'As partes acima qualificadas firmam o presente instrumento particular de contrato de prestação de serviços, que se rege pelas cláusulas seguintes.', 1, 102),
  ('vcl_c02_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 2, 'Objeto', 'fixa', NULL, 'O presente contrato tem por objeto a prestação de serviços profissionais especializados em Arquitetura e Urbanismo pela CONTRATADA, nos termos do escopo descrito neste contrato.', 1, 201),
  ('vcl_c02_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 2, 'Proposta integrada ao contrato', 'opcional', NULL, 'A proposta comercial {proposta}, aceita pelo CONTRATANTE, integra este contrato naquilo que não o contrariar.', 1, 202),
  ('vcl_c03_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 3, 'Compatibilização', 'opcional', NULL, 'A CONTRATADA compatibiliza o projeto de arquitetura com os projetos complementares, desde que elaborados por profissionais habilitados contratados pelo CONTRATANTE.', 1, 301),
  ('vcl_c04_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 4, 'Prazos condicionados', 'fixa', NULL, 'Os prazos acima dependem do cumprimento, pelo CONTRATANTE, de suas obrigações e de seus prazos de aprovação.', 1, 401),
  ('vcl_c04_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 4, 'Elementos iniciais', 'opcional', NULL, 'A contagem dos prazos começa no dia útil seguinte à entrega, pelo CONTRATANTE, dos elementos necessários ao projeto, que a CONTRATADA solicita na assinatura deste contrato e que devem ser entregues em até 5 (cinco) dias úteis.', 1, 402),
  ('vcl_c04_03', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 4, 'Tempo fora do prazo', 'opcional', NULL, 'Não contam no prazo da CONTRATADA os dias em que o projeto estiver em apreciação pelo CONTRATANTE ou em análise por órgãos públicos e terceiros.', 1, 403),
  ('vcl_c04_04', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 4, 'Ajuste de prazos', 'opcional', NULL, 'Os prazos podem ser reduzidos ou ampliados por acordo escrito entre as partes.', 1, 404),
  ('vcl_c04_05', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 4, 'Executiva após a aprovação legal', 'fixa', 'legal_executiva', 'As etapas da fase Executiva só têm suas datas confirmadas após a aprovação do projeto legal pelos órgãos competentes.', 1, 405),
  ('vcl_c05_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 5, 'Apresentação das etapas', 'fixa', NULL, 'Ao fim de cada etapa, a CONTRATADA apresenta ao CONTRATANTE os documentos produzidos, para apreciação.', 1, 501),
  ('vcl_c05_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 5, 'Prazo de apreciação', 'opcional', NULL, 'O CONTRATANTE tem 5 (cinco) dias úteis para apreciar cada etapa e comunicar sua decisão por escrito. Sem manifestação nesse prazo, a etapa se considera aprovada.', 1, 502),
  ('vcl_c05_03', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 5, 'Termo de aprovação', 'opcional', NULL, 'A aprovação de cada etapa se formaliza pela assinatura do Termo de Recebimento e Aprovação de Etapa, fornecido pela CONTRATADA, ou por mensagem escrita do CONTRATANTE que aprove a etapa.', 1, 503),
  ('vcl_c05_04', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 5, 'Soluções aprovadas', 'opcional', NULL, 'Aprovada a etapa {etapa_aprovada}, as soluções aprovadas não se alteram a pedido do CONTRATANTE, salvo como alteração de escopo, nos termos deste contrato.', 1, 504),
  ('vcl_c05_05', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 5, 'Correções da documentação', 'opcional', NULL, 'Correções e complementos da documentação técnica podem ser pedidos em qualquer etapa e não contam como revisão.', 1, 505),
  ('vcl_c06_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 6, 'Vencimento e tolerância', 'opcional', NULL, 'Cada parcela vence na data ou no marco indicado acima, com tolerância de 3 (três) dias úteis, sem multa nem juros.', 1, 601),
  ('vcl_c06_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 6, 'Tributos', 'fixa', NULL, 'Cabe à CONTRATADA o recolhimento dos tributos que incidem sobre os honorários deste contrato.', 1, 602),
  ('vcl_c06_03', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 6, 'Atraso no pagamento', 'opcional', NULL, 'Em caso de atraso no pagamento, incidem sobre o valor devido multa de 2% (dois por cento), juros de mora de 1% (um por cento) ao mês e correção monetária pelo IPCA/IBGE, ou pelo índice que o substituir.', 1, 603),
  ('vcl_c06_04', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 6, 'Suspensão por atraso', 'opcional', NULL, 'Enquanto durar o atraso, a CONTRATADA não fica obrigada a dar continuidade aos serviços, e os prazos se prorrogam pelo mesmo período.', 1, 604),
  ('vcl_c06_05', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 6, 'Reajuste', 'opcional', NULL, 'As parcelas que vencerem mais de 12 (doze) meses após a assinatura deste contrato são reajustadas pela variação do IPCA/IBGE no período.', 0, 605),
  ('vcl_c07_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 7, 'Reembolso', 'fixa', 'despesas', 'O CONTRATANTE reembolsa à CONTRATADA as despesas acima que ela vier a pagar, em até 30 (trinta) dias da apresentação dos comprovantes.', 1, 701),
  ('vcl_c08_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 8, 'Elementos e informações', 'fixa', NULL, 'O CONTRATANTE entrega à CONTRATADA, nos prazos pedidos, os elementos e as informações necessários à execução dos serviços.', 1, 801),
  ('vcl_c08_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 8, 'Projetos complementares', 'opcional', NULL, 'O CONTRATANTE contrata profissionais habilitados para a elaboração e a aprovação dos projetos complementares, quando necessários.', 1, 802),
  ('vcl_c08_03', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 8, 'Pagamento', 'fixa', NULL, 'O CONTRATANTE paga os honorários nos prazos combinados.', 1, 803),
  ('vcl_c08_04', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 8, 'Taxas de aprovação', 'fixa', 'projeto_legal', 'O CONTRATANTE paga as taxas necessárias à aprovação do projeto na Prefeitura e nos demais órgãos competentes, e à emissão do alvará.', 1, 804),
  ('vcl_c08_05', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 8, 'Obra conforme o projeto', 'opcional', NULL, 'O CONTRATANTE executa a obra respeitando integralmente o projeto.', 1, 805),
  ('vcl_c08_06', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 8, 'Interlocutor e comunicações', 'opcional', NULL, 'O CONTRATANTE indica uma pessoa para responder pelas decisões do projeto. As comunicações trocadas por e-mail ou WhatsApp, entre os contatos informados pelas partes, valem como comunicação escrita para os fins deste contrato.', 1, 806),
  ('vcl_c09_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 9, 'Execução dos serviços', 'fixa', NULL, 'A CONTRATADA executa os serviços descritos no escopo deste contrato, nos prazos estabelecidos.', 1, 901),
  ('vcl_c09_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 9, 'Equipe', 'opcional', NULL, 'A CONTRATADA mantém sob sua responsabilidade a equipe necessária aos serviços, arcando com os encargos correspondentes.', 1, 902),
  ('vcl_c09_03', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 9, 'Aprovação na Prefeitura', 'fixa', 'projeto_legal', 'A CONTRATADA assume, como autora, a responsabilidade técnica pela aprovação do projeto na Prefeitura do município da obra, atendendo prontamente às exigências e aos esclarecimentos pedidos pelo órgão.', 1, 903),
  ('vcl_c09_04', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 9, 'RRT', 'fixa', NULL, 'A CONTRATADA registra no CAU o RRT (Registro de Responsabilidade Técnica) de cada atividade técnica deste contrato.', 1, 904),
  ('vcl_c09_05', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 9, 'Guarda dos arquivos', 'opcional', NULL, 'A CONTRATADA guarda os arquivos do projeto por 5 (cinco) anos após o encerramento do contrato.', 1, 905),
  ('vcl_c10_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 10, 'Modificações após aprovação', 'opcional', NULL, 'Modificações pedidas pelo CONTRATANTE depois da aprovação de uma etapa são cobradas à parte, em valor combinado entre as partes antes de começarem.', 1, 1001),
  ('vcl_c10_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 10, 'Acréscimo acima de 10%', 'opcional', NULL, 'Se os serviços contratados aumentarem mais de 10% (dez por cento) em relação ao previsto, os novos valores e prazos são definidos em aditivo a este contrato.', 1, 1002),
  ('vcl_c10_03', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 10, 'Alterações por escrito', 'fixa', NULL, 'Nenhuma alteração deste contrato tem validade sem acordo escrito e assinado pelas partes.', 1, 1003),
  ('vcl_c11_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 11, 'Direitos autorais', 'fixa', NULL, 'Os direitos autorais sobre o projeto pertencem à CONTRATADA, nos termos da Lei 9.610/1998, da Lei 12.378/2010 e da Resolução CAU/BR 67/2013. Nenhuma alteração no projeto ou na obra dele resultante pode ser feita sem o seu consentimento por escrito.', 1, 1101),
  ('vcl_c11_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 11, 'Uso único do projeto', 'opcional', NULL, 'O projeto só pode ser executado no imóvel indicado no objeto deste contrato, e não pode ser replicado em outro local pelo CONTRATANTE.', 1, 1102),
  ('vcl_c11_03', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 11, 'Alterações na obra', 'opcional', NULL, 'A CONTRATADA não responde por alterações feitas durante a obra em desacordo com o projeto, nem por alterações pedidas ou feitas pelo CONTRATANTE em desacordo com a legislação em vigor.', 1, 1103),
  ('vcl_c11_04', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 11, 'Crédito da autoria', 'opcional', NULL, 'Toda peça de publicidade ou divulgação sobre o objeto deste contrato menciona, com destaque, o nome da CONTRATADA como autora do projeto.', 1, 1104),
  ('vcl_c11_05', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 11, 'Divulgação de imagens', 'opcional', NULL, 'A CONTRATADA pode divulgar imagens e textos sobre o projeto e a obra em seu portfólio, site, redes sociais e publicações, preservadas as informações pessoais e a segurança do CONTRATANTE, que pode pedir por escrito a omissão de dados que o identifiquem.', 1, 1105),
  ('vcl_c11_06', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 11, 'Aviso do início da obra', 'opcional', NULL, 'Não sendo contratada para a responsabilidade técnica pela execução da obra, a CONTRATADA tem o direito de ser comunicada por escrito, pelo CONTRATANTE, do início da obra.', 1, 1106),
  ('vcl_c12_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 12, 'Sigilo', 'opcional', NULL, 'As partes mantêm em sigilo as informações de caráter pessoal, comercial ou técnico que receberem uma da outra em razão deste contrato, salvo as necessárias à aprovação do projeto e à sua execução.', 1, 1201),
  ('vcl_c12_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 12, 'Proteção de dados', 'opcional', NULL, 'Os dados pessoais do CONTRATANTE são tratados pela CONTRATADA apenas para a execução deste contrato e o cumprimento de obrigações legais, nos termos da Lei 13.709/2018 (Lei Geral de Proteção de Dados).', 1, 1202),
  ('vcl_c13_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 13, 'Caso fortuito e força maior', 'opcional', NULL, 'Caso fortuito e força maior são os previstos no art. 393 do Código Civil. A parte impedida de cumprir uma obrigação por esse motivo avisa a outra por escrito em até 24 (vinte e quatro) horas, descrevendo o evento, seus efeitos e a duração estimada; a obrigação afetada fica suspensa enquanto durar o evento, e o contrato continua em vigor. A suspensão não dispensa o pagamento dos valores devidos antes do evento.', 1, 1301),
  ('vcl_c13_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 13, 'Rescisão sem culpa', 'opcional', NULL, 'O contrato se encerra de pleno direito, sem penalidade para as partes e sem prejuízo das obrigações vencidas, em caso de falência ou recuperação judicial ou extrajudicial de qualquer delas, de norma legal que torne o contrato impraticável, ou de caso fortuito ou força maior que impeça por completo a sua execução.', 1, 1302),
  ('vcl_c13_03', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 13, 'Rescisão por descumprimento', 'opcional', NULL, 'O descumprimento das obrigações deste contrato por qualquer das partes permite à outra rescindi-lo, com as consequências previstas a seguir.', 1, 1303),
  ('vcl_c13_04', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 13, 'Rescisão pelo contratante', 'opcional', NULL, 'Se o contrato for rescindido por iniciativa ou culpa do CONTRATANTE, este paga à CONTRATADA multa de 25% (vinte e cinco por cento) sobre o saldo dos honorários ainda não pagos, e os valores já pagos pelas etapas concluídas ficam com a CONTRATADA, sem prejuízo da indenização por perdas e danos, nos termos dos arts. 402 a 404 do Código Civil.', 1, 1304),
  ('vcl_c13_05', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 13, 'Rescisão pela contratada', 'opcional', NULL, 'Se o contrato for rescindido por iniciativa ou culpa da CONTRATADA, esta devolve ao CONTRATANTE os valores pagos por etapas não entregues e autoriza o uso do material já entregue para que outro profissional conclua o serviço, mantida a autoria da CONTRATADA sobre o que elaborou.', 1, 1305),
  ('vcl_c14_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 14, 'Sem vínculo empregatício', 'fixa', NULL, 'Este contrato não cria vínculo empregatício entre as partes.', 1, 1401),
  ('vcl_c14_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 14, 'Acordo integral', 'fixa', NULL, 'Este contrato reúne todo o acordo entre as partes e substitui os acordos e entendimentos anteriores, orais ou escritos, sobre o mesmo assunto.', 1, 1402),
  ('vcl_c14_03', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 14, 'Nulidade parcial', 'opcional', NULL, 'Se alguma disposição deste contrato for considerada inválida, ilegal ou inaplicável, as demais continuam válidas, e as partes negociam de boa-fé a sua substituição, mantida a intenção original.', 1, 1403),
  ('vcl_c14_04', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 14, 'Tolerância', 'opcional', NULL, 'A tolerância de qualquer das partes com o descumprimento de uma obrigação pela outra é mera liberalidade: não constitui novação, renúncia, alteração do contrato nem precedente.', 1, 1404),
  ('vcl_c14_05', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 14, 'Casos omissos', 'opcional', NULL, 'Os casos omissos são resolvidos por acordo entre as partes, por aditivo a este contrato.', 1, 1405),
  ('vcl_c15_01', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 15, 'Foro', 'fixa', NULL, 'As partes elegem o foro da Comarca de João Pessoa/PB para resolver qualquer questão deste contrato, com renúncia a qualquer outro, por mais especial que seja.', 1, 1501),
  ('vcl_c15_02', '2026-11-21T05:00:00.000Z', '2026-11-21T05:00:00.000Z', 'migracao', 'migracao', 'geral', 15, 'Assinatura eletrônica', 'fixa', NULL, 'As partes reconhecem a validade da assinatura deste contrato por meio eletrônico, nos termos da Lei 14.063/2020 e do art. 784, § 4º, do Código de Processo Civil, dispensada a assinatura de testemunhas.', 1, 1502);
INSERT INTO vendas_clausulas (id, criado_em, atualizado_em, criado_por, atualizado_por, grupo, texto, padrao, ordem)
